const sceneOptions={EN:['Glamour / adult fashion','Portrait','Cinematic scene','Product','Nature','Atmosphere','Action','Own category','Subtle','Natural','Dynamic'],HU:['Glamour / felnőtt divat','Portré','Filmes jelenet','Termék','Természet','Hangulatkép','Akció','Saját kategória','Visszafogott','Természetes','Dinamikus'],DE:['Glamour / Erwachsenenmode','Porträt','Filmszene','Produkt','Natur','Atmosphäre','Action','Eigene Kategorie','Dezent','Natürlich','Dynamisch'],FR:['Glamour / mode adulte','Portrait','Scène cinéma','Produit','Nature','Atmosphère','Action','Catégorie libre','Subtil','Naturel','Dynamique'],ES:['Glamour / moda adulta','Retrato','Escena de cine','Producto','Naturaleza','Ambiente','Acción','Categoría propia','Sutil','Natural','Dinámico'],IT:['Glamour / moda adulta','Ritratto','Scena cinematografica','Prodotto','Natura','Atmosfera','Azione','Categoria personale','Leggero','Naturale','Dinamico'],PT:['Glamour / moda adulta','Retrato','Cena de cinema','Produto','Natureza','Atmosfera','Ação','Categoria própria','Sutil','Natural','Dinâmico'],PL:['Glamour / moda dorosłych','Portret','Scena filmowa','Produkt','Przyroda','Atmosfera','Akcja','Własna kategoria','Subtelny','Naturalny','Dynamiczny']};
export function sceneLabels(lang){return Object.fromEntries(sceneLabelKeys.map((k,i)=>[k,(sceneWords[lang]||sceneWords.EN)[i]]));}
export function sceneOptionLabels(lang){return sceneOptions[lang]||sceneOptions.EN;}
export function validateSceneLabels(){return Object.keys(sceneWords).length===8&&Object.values(sceneWords).every(v=>v.length===sceneLabelKeys.length&&v.every(Boolean))&&Object.values(sceneOptions).every(v=>v.length===11);}
